insert into public.ch_planting_distance_rules (height_class,label_de,min_boundary_distance_m,note,disclaimer,source) values
('forst','Forst/Grossbaum','6.0','Grossbäume, Nuss-/Kastanienbäume und Bäume über ~12 m Höhe sowie Waldnähe. Mehrere Kantone setzen 5–6 m (z.B. BE 5 m, AG 6 m für Nuss/Kastanie/>12 m). Für Waldabstand gelten zusätzlich kantonale Wald-/Baugesetze.','Richtwert — der gesetzliche Grenzabstand ist in der Schweiz kantonal/kommunal geregelt (EG zum ZGB). Im Zweifel bei Gemeinde/Bauamt oder Geometer abklären.','Ratgeber-Faustwert (hausinfo.ch, mobiliar.ch Grenzabstand, beobachter.ch Nachbarrecht); kantonale EG-ZGB-Praxis BE/AG'),
('hoch','Hoch (Hochstamm-Bäume über 4 m)','4.0','Hochstamm-Obstbäume und höhere Bäume (Wuchshöhe >4 m). Verbreiteter Richtwert ~3–4 m (z.B. BE 3 m Hochstamm-Obst); Grundsatz: je höher, desto grösser der Abstand.','Richtwert — der gesetzliche Grenzabstand ist in der Schweiz kantonal/kommunal geregelt (EG zum ZGB). Im Zweifel bei Gemeinde/Bauamt oder Geometer abklären.','Ratgeber-Faustwert (hausinfo.ch, mobiliar.ch Grenzabstand, beobachter.ch Nachbarrecht); kantonale EG-ZGB-Praxis BE/AG'),
('mittel','Mittel (Bäume/Spalierobst 2–4 m)','1.0','Mittelhohe Gehölze, Spalier-/Niederstammobst, kleinere Zierbäume (Wuchshöhe ~2–4 m). Faustregel ~1 m; oft hälftige Höhe als Abstand bis zu kantonalem Maximum.','Richtwert — der gesetzliche Grenzabstand ist in der Schweiz kantonal/kommunal geregelt (EG zum ZGB). Im Zweifel bei Gemeinde/Bauamt oder Geometer abklären.','Ratgeber-Faustwert (hausinfo.ch, mobiliar.ch Grenzabstand, beobachter.ch Nachbarrecht); kantonale EG-ZGB-Praxis'),
('niedrig','Niedrig (Sträucher/Hecken bis 2 m)','0.5','Übliche Faustregel für Gartenpflanzen, Zierhecken, niedrige Sträucher (Wuchshöhe bis ~2 m). Gemessen ab Mitte des Pflanzorts. Viele Kantone nennen 0.5–0.6 m (z.B. ZH 0.60 m, AG 0.6 m ab Heckenmitte).','Richtwert — der gesetzliche Grenzabstand ist in der Schweiz kantonal/kommunal geregelt (EG zum ZGB). Im Zweifel bei Gemeinde/Bauamt oder Geometer abklären.','Ratgeber-Faustwert (hausinfo.ch, mobiliar.ch Grenzabstand, beobachter.ch Nachbarrecht); kantonale EG-ZGB-Praxis ZH/AG')
